     self,
     paging::FrameNumber,
 };
 use ::bitmap::Bitmap;
 use ::config::constants;
 use ::core::{
     hint::unlikely,
     mem::MaybeUninit,
     sync::atomic::{
         AtomicBool,
         Ordering,
     },
 };
 use ::sys::{
     error::{
         Error,
         ErrorCode,
     },
     mm::Address,
 };
 use ::vstd::prelude::*;

 #[cfg(verus_keep_ghost)]
 include!("frame.spec.rs");

 #[cfg(verus_keep_ghost)]
 include!("frame.proof.rs");

 //==================================================================================================
